def prose(value):
    return re.sub(r'\[\[([^|]+)\|([^\]]+)\]\]', lambda match: '<a href="/' + match[1] + '">' + match[2] + '</a>', html.escape(value))

lessons = [
 dict(slug='security-multiple-filter-chains', title='Spring Security multiple filter chains: match the whole request surface', summary='A securityMatcher chooses which chain runs; requestMatchers inside that chain only authorize requests it already owns.', blocks=[
  ('Chain selection comes first', 'A receipt API uses bearer tokens while an operator console uses browser login. Two SecurityFilterChain beans can keep those mechanisms apart. Order the API chain before a final catch-all chain and give it a narrow securityMatcher. If no chain matches a request, Spring Security does not protect it. That is a different failure from a matched request denied by [[spring/security-matcher-order|an authorization rule]]. A typo in an API prefix can therefore expose an endpoint before any hasAuthority check executes.'),
  ('Include generated endpoints', 'A chain-scoped matcher also affects endpoints supplied by filters. Form login or logout URLs outside the chain matcher can disappear, producing a 404 rather than an authentication response. Either place those endpoints inside the console path or use a suitable catch-all browser chain. Do not assume a downstream chain contributes its authentication filters to a request that matched an earlier chain; the first matching chain owns that request. [[spring/security-filter-chain|Filter order]] still matters inside each selected chain.'),
  ('Prove coverage', 'List every controller, callback, management route and generated login/logout URL. Probe each without credentials, with the wrong credential type and with an authorized identity. Assert that a newly added route falls into a deny-by-default chain. A route inventory test is more reliable than reading a matcher pattern and assuming it covers every method and path.')], code='@Bean @Order(1)\nSecurityFilterChain receiptApi(HttpSecurity http) throws Exception {\n    http.securityMatcher("/api/receipts/**")\n        .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())\n        .oauth2ResourceServer(oauth -> oauth.jwt(Customizer.withDefaults()));\n    return http.build();\n}\n@Bean\nSecurityFilterChain remainingRoutes(HttpSecurity http) throws Exception {\n    http.authorizeHttpRequests(auth -> auth.anyRequest().denyAll());\n    return http.build();\n}', language='java', cost='Each request tests ordered chain matchers until one matches. A few explicit chains add negligible work, while broad or overlapping patterns raise review cost and can select the wrong credential mechanism.', mistakes=['Do not leave routes outside every SecurityFilterChain.','Do not confuse a chain securityMatcher with authorization requestMatchers.','Do not put generated login or logout endpoints outside their owning chain.'], related=['spring/security-filter-chain','spring/security-matcher-order','spring/health-probe-security','spring/oauth2-login-session','spring/jwt-resource-server'], backlink='spring/security-matcher-order'),
 dict(slug='stateless-api-session-request-cache', title='Spring Security stateless APIs: remove session and saved-request assumptions', summary='A bearer-token API should authenticate each call independently and should not rely on a browser session or redirect cache.', blocks=[
  ('A stateless boundary', 'A receipt endpoint receives a bearer token on every request. SessionCreationPolicy.STATELESS tells Spring Security not to use an HTTP session to obtain the SecurityContext. It also changes the saved-request behavior used by browser login flows. A client that expects an HTML redirect to a login page is using the wrong API contract. Return an authentication challenge or error response, then let the client retry with a valid token. [[spring/security-authentication-vs-denial|401 versus 403]] should remain distinguishable.'),
  ('Keep browser and API rules separate', 'A sibling operator console may still use a session, a login redirect and [[spring/session-csrf-boundary|CSRF protection]]. Put that browser flow in its own chain instead of disabling sessions or CSRF globally. Stateless does not mean every dependency is stateless: an opaque-token introspection call, a rate limiter and a tenant lookup still have network and cache state. It means the API does not use a login session as its authentication source.'),
  ('Verify the actual response', 'Send an unauthenticated GET and POST, then a valid bearer request, then another request without the token. Confirm the final call is unauthorized and that the API did not issue an application session cookie. Inspect Location headers to ensure no HTML login redirect escaped into the API. Include a cross-origin browser request in this test plan; [[spring/cors-preflight-security-order|CORS preflight]] has separate handling from authentication.')], code='http.securityMatcher("/api/**")\n    .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n    .requestCache(cache -> cache.disable())\n    .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())\n    .oauth2ResourceServer(oauth -> oauth.jwt(Customizer.withDefaults()));', language='java', cost='Per-request token verification adds CPU and possibly key-cache work; it avoids session storage and replication. A remote token check adds network latency unless its bounded cache policy is explicit.', mistakes=['Do not expect a previous bearer request to authenticate the next request without a token.','Do not disable session behavior on a separate browser-login chain.','Do not return a login-page redirect from a JSON API.'], related=['spring/security-multiple-filter-chains','spring/jwt-resource-server','spring/security-authentication-vs-denial','spring/session-csrf-boundary','spring/cors-preflight-security-order'], backlink='spring/jwt-resource-server'),
 dict(slug='jwt-authority-claim-mapping', title='Spring JWT authority mapping: convert a trusted claim into one deliberate namespace', summary='A signed token can carry scopes or roles, but Spring authorization checks the GrantedAuthority strings produced by a converter.', blocks=[
  ('Signature before authority', 'A receipt token has a claims field named permissions containing receipt.read and receipt.issue. The resource server must validate signature, issuer, audience and time before using those values. [[spring/jwt-resource-server|JWT validation]] establishes token trust; the converter turns a trusted claim into application authorities. If a controller checks SCOPE_receipt.issue while the converter emits PERM_receipt.issue, access is denied. If the converter maps an untrusted header or request parameter, the check becomes meaningless.'),
  ('Keep the namespace explicit', 'Configure JwtGrantedAuthoritiesConverter for the exact claim name and prefix. Put that converter inside JwtAuthenticationConverter and attach it to the resource-server chain. Avoid silently accepting several claim names or treating arbitrary token strings as roles. [[spring/role-authority-prefix|Role and authority prefixes]] are string conventions, so document the issuer contract and test the final Authentication rather than only the decoded token. Tenant ownership remains a separate database decision from a permission string.'),
  ('Test absent and malformed claims', 'Use signed test tokens or a trusted decoder fixture. Verify one permission grants its intended action, an absent permissions claim grants none, and a similarly named permission fails. Test both the HTTP matcher and [[spring/method-authorization|method guard]] if they enforce the same action. Do not assume a role change takes effect on already-issued self-contained tokens; token lifetime and revocation policy set that delay.')], code='JwtGrantedAuthoritiesConverter grants = new JwtGrantedAuthoritiesConverter();\ngrants.setAuthoritiesClaimName("permissions");\ngrants.setAuthorityPrefix("PERM_");\nJwtAuthenticationConverter converter = new JwtAuthenticationConverter();\nconverter.setJwtGrantedAuthoritiesConverter(grants);\nhttp.oauth2ResourceServer(oauth -> oauth.jwt(jwt -> jwt.jwtAuthenticationConverter(converter)));', language='java', cost='Authority conversion is linear in the number of claim values. Verification of a signed JWT usually dominates the local cost; oversized permission arrays increase token size on every call.', mistakes=['Do not authorize from a claim before token validation.','Do not mix role and scope prefixes without an explicit mapping contract.','Do not let a broad permission replace a tenant-specific ownership check.'], related=['spring/jwt-resource-server','spring/role-authority-prefix','spring/jwt-issuer-audience-boundary','spring/scope-versus-tenant-access','spring/method-authorization'], backlink='spring/role-authority-prefix'),
 dict(slug='jwt-clock-skew-window', title='Spring JWT clock skew: bound tolerance without extending token trust blindly', summary='Clock tolerance can absorb small issuer and resource-server drift, but it also expands the effective acceptance window around token timestamps.', blocks=[
  ('Name the clock problem', 'A newly issued receipt token can arrive at a resource server whose clock is slightly behind and appear not yet valid. A token near expiry can appear expired on a server ahead of the issuer. JwtTimestampValidator accepts a bounded skew for exp and nbf checks. Do not remove timestamp validation to solve clock drift. [[spring/jwt-issuer-audience-boundary|Issuer and audience validation]] still needs to run alongside it.'),
  ('Compose validators, do not replace trust', 'If a custom NimbusJwtDecoder is installed to adjust skew, attach a validator that includes the issuer check and the timestamp check. Replacing the default validator with only JwtTimestampValidator can accidentally drop issuer validation. Keep the skew to the measured clock error plus a small margin, and monitor host time synchronization. A five-minute tolerance turns a five-minute access-token lifetime into a materially wider acceptance period near expiry.'),
  ('Exercise boundaries', 'Generate tokens just before nbf, just after exp, with the wrong issuer and with the wrong audience. The first two should follow the chosen tolerance; the last two must fail regardless of time. Make tests use a controlled clock where possible rather than sleeping. [[spring/jwt-jwks-rotation-window|Key rotation]] and timestamp tolerance are different windows: a still-valid token needs its signing key available, but a rotated key does not justify accepting expired tokens.')], code='NimbusJwtDecoder decoder = NimbusJwtDecoder.withIssuerLocation(issuerLocation).build();\nOAuth2TokenValidator<Jwt> validity = new DelegatingOAuth2TokenValidator<>(\n    new JwtTimestampValidator(Duration.ofSeconds(37)),\n    new JwtIssuerValidator(issuerLocation),\n    new JwtClaimValidator<List<String>>("aud", audiences ->\n        audiences != null && audiences.contains("receipt-api"))\n);\ndecoder.setJwtValidator(validity);', language='java', cost='Timestamp checks are constant-time. A wider skew has little compute cost but increases the period in which a stolen or expired token may be accepted.', mistakes=['Do not turn off exp or nbf validation to hide unsynchronized clocks.','Do not replace the decoder validator with a timestamp-only validator and lose issuer checks.','Do not assume key-overlap and clock-skew settings solve the same failure.'], related=['spring/jwt-issuer-audience-boundary','spring/jwt-jwks-rotation-window','spring/jwt-resource-server','spring/security-authentication-vs-denial','spring/oauth2-client-token-lifecycle'], backlink='spring/jwt-issuer-audience-boundary'),
 dict(slug='spa-csrf-token-refresh', title='Spring Security SPA CSRF: refresh the token after login and logout', summary='A cookie-authenticated SPA must send a CSRF value in a non-cookie request part, then obtain a fresh value after authentication transitions.', blocks=[
  ('A cookie is not the proof', 'Browsers attach login cookies automatically to cross-site requests. A state-changing receipt command therefore needs a separate CSRF token in a header or form field. Copying the login cookie into another cookie proves nothing. CookieCsrfTokenRepository can expose an XSRF-TOKEN cookie and read X-XSRF-TOKEN from a request header, but the JavaScript app must actually send the header. [[spring/session-csrf-boundary|Session CSRF]] is the base boundary; a pure bearer API has a different credential model.'),
  ('Handle token lifecycle', 'Spring Security can defer loading a token until needed, and its request handling includes protection against token disclosure attacks. A single-page client reading the cookie needs the SPA-specific handler strategy for the raw cookie value. Authentication success and logout clear the old token; the client must fetch a fresh token before its next unsafe request. Spring Security 7 spa() configures the server-side SPA token handling; the client still makes the refresh call. Do not solve a post-login 403 by disabling CSRF for all application routes. Keep a small same-origin token bootstrap endpoint or response contract.'),
  ('Test in a browser-shaped client', 'Attempt POST with the session cookie and no header; expect denial. Repeat with a matching token header; expect success. Then log in or out and confirm the old token no longer authorizes a write. Test cross-origin credential settings separately because [[spring/cors-preflight-security-order|CORS]] controls which origins may read responses, not whether a forged write is valid. A regular HTTP client test must explicitly model cookie and header behavior.')], code='http.csrf(csrf -> csrf.spa());\n// The SPA sends the issued token in X-XSRF-TOKEN on unsafe requests.', language='java', cost='Token generation and comparison are small, but session or cookie loading adds per-request work. A bootstrap call after login adds one round trip; it preserves the write boundary.', mistakes=['Do not rely on SameSite alone for every browser and deployment topology.','Do not disable CSRF globally because the SPA receives 403 after login.','Do not treat CORS approval as a CSRF defense.'], related=['spring/session-csrf-boundary','spring/bearer-post-csrf-boundary','spring/oauth2-login-session','spring/cors-preflight-security-order','spring/session-cookie-policy'], backlink='spring/session-csrf-boundary'),
 dict(slug='opaque-token-introspection-budget', title='Spring opaque-token introspection: budget the authorization-server dependency', summary='Opaque bearer tokens require a trusted introspection response per validation path, making network failure and cache staleness part of API availability.', blocks=[
  ('The token is only a handle', 'An opaque token tells the receipt service nothing until an authorization server confirms that it is active and returns its attributes. Spring Resource Server can call an introspection endpoint through an OpaqueTokenIntrospector. This can make revocation visible sooner than a self-contained JWT, but it adds a remote dependency to authentication. [[spring/jwt-resource-server|JWT validation]] instead checks a signed token locally, subject to key and expiry rules.'),
  ('Bound calls and caching', 'Configure the endpoint, client credentials and HTTP timeouts from protected settings. Never print bearer tokens or introspection credentials in logs. If a local cache is introduced, bind it to token identity, expire entries no later than the returned token expiry and choose an explicit revocation delay. A cache that stores active results indefinitely defeats the operational reason for introspection. [[spring/jdbc-pool-capacity|Downstream capacity]] thinking applies here too: a login provider outage can saturate request workers if every call waits at once.'),
  ('Fail closed and observe', 'Test active, inactive, malformed and expired tokens, plus a timeout and a server error. Unavailable introspection must not turn into anonymous permission to issue receipts. Distinguish authentication failure from dependency failure in internal metrics without exposing token values. Measure p95 introspection latency and concurrent in-flight calls, then set a request budget that leaves room for the actual receipt work.')], code='spring.security.oauth2.resourceserver.opaquetoken.introspection-uri=${INTROSPECTION_URI}\nspring.security.oauth2.resourceserver.opaquetoken.client-id=${INTROSPECTION_CLIENT_ID}\nspring.security.oauth2.resourceserver.opaquetoken.client-secret=${INTROSPECTION_CLIENT_SECRET}', language='properties', cost='Without caching, authorization calls grow O(requests) and add network latency per request. A bounded cache reduces calls but extends the window before revocation is observed.', mistakes=['Do not cache a positive introspection result without an expiry policy.','Do not interpret an introspection outage as a valid token.','Do not log bearer values or introspection client secrets.'], related=['spring/jwt-resource-server','spring/oauth2-client-token-lifecycle','spring/security-authentication-vs-denial','spring/jwt-jwks-rotation-window','spring/metric-cardinality'], backlink='spring/oauth2-client-token-lifecycle'),
 dict(slug='security-content-policy-rollout', title='Spring Security CSP rollout: enforce tested asset rules at the response edge', summary='Content Security Policy is application-specific, so configure it for the actual scripts and frames rather than assuming default headers cover it.', blocks=[
  ('Defaults do not supply a policy', 'Spring Security adds several response headers by default, but it cannot infer a safe Content Security Policy for a receipt console. A restrictive policy can reduce the harm of injected markup, yet it does not replace output encoding or input validation. Start with the real asset inventory: scripts, styles, images, fonts and frames. [[spring/security-filter-chain|The selected filter chain]] must add the header to the browser responses that render those assets.'),
  ('Roll out with evidence', 'Use a report-only policy first on representative pages. Inspect violations for inline scripts, third-party widgets and browser extensions; not every report indicates a required source. Remove or nonce inline code where practical, then enforce a policy narrow enough for the product. A broad wildcard or unsafe-inline may keep the page working while weakening the rule. Keep any reporting endpoint rate-limited and avoid storing complete user URLs if they carry sensitive query parameters.'),
  ('Test every page family', 'Open login, receipt list, receipt detail and error pages with the enforced policy. Check the browser console and actual HTTP header, including reverse-proxy behavior. An API response that returns only JSON may need a different policy than the operator UI. [[spring/cors-preflight-security-order|CORS]] and CSP answer different questions: CORS gates cross-origin response access, while CSP constrains resources a rendered page may load.')], code='http.headers(headers -> headers\n    .contentSecurityPolicy(csp -> csp\n        .policyDirectives("default-src \'self\'; script-src \'self\'; object-src \'none\'; frame-ancestors \'none\'")));', language='java', cost='The header adds few bytes per response. Report collection, asset refactoring and browser regression testing are the real costs; an overbroad policy offers little protection.', mistakes=['Do not assume Spring Security creates a CSP by default.','Do not enforce an untested policy that breaks login or checkout scripts.','Do not use CSP as a replacement for encoding untrusted output.'], related=['spring/security-filter-chain','spring/security-multiple-filter-chains','spring/cors-preflight-security-order','spring/session-cookie-policy','spring/upload-generated-filename'], backlink='spring/security-filter-chain'),
 dict(slug='method-security-ownership-bean', title='Spring method security ownership bean: authorize before the service changes state', summary='A named authorization bean can centralize tenant ownership checks while @PreAuthorize keeps the decision before a protected method runs.', blocks=[
  ('Keep the guard near the command', 'A receipt mutation is dangerous even when its controller route requires a generic write scope. The service must still prove that the signed-in tenant owns the target receipt. A named bean used by @PreAuthorize can perform that check before the method body executes. This avoids the [[spring/method-security-postauthorize-side-effects|post-authorization side-effect trap]]. It does not remove the need for tenant predicates in the final database write, because ownership can change between a preliminary check and mutation.'),
  ('Use a narrow input contract', 'Give the authorization bean the authenticated tenant and receipt ID, not an entire request body or a detached entity. Reject missing identity and nonexistent receipts without disclosing another tenant’s record. The repository should query by both tenant and ID and use an index that supports that predicate. [[spring/method-security-proxy-boundary|Method security advice]] runs through the Spring bean proxy, so self-invocation inside the same service does not activate the annotation.'),
  ('Test bypass attempts', 'Call the service through its Spring bean with an owner, another tenant and no authentication. Assert only the owner reaches the mutation. Then call the repository write in a concurrent test with a changed owner or revision to prove that the final predicate still protects the row. A method guard is one layer; [[spring/tenant-versioned-write|versioned tenant writes]] close the race at the storage boundary.')], code='@PreAuthorize("@receiptAccess.owns(authentication, #tenantId, #receiptId)")\n@Transactional\npublic void voidReceipt(UUID tenantId, UUID receiptId) {\n    repository.voidOwnedReceipt(tenantId, receiptId);\n}\n// receiptAccess is a Spring bean that checks the authenticated tenant.', language='java', cost='A database-backed ownership check may add one SELECT before the write. A tenant-and-version predicate on the write adds little query cost with the right index and protects against a stale authorization decision.', mistakes=['Do not treat a write scope as proof of ownership of every receipt.','Do not put the first ownership check after a method has already mutated state.','Do not rely on @PreAuthorize during self-invocation that bypasses the bean proxy.'], related=['spring/method-authorization','spring/method-security-proxy-boundary','spring/method-security-postauthorize-side-effects','spring/tenant-versioned-write','spring/scope-versus-tenant-access'], backlink='spring/method-authorization'),
]

titles = {path: row['title'] for path,row in by_path.items()}
titles.update({'spring/'+item['slug']:item['title'] for item in lessons})
for number,item in enumerate(lessons):
    path='spring/'+item['slug']
    assert path not in by_path,path
    for target in item['related']: assert target in titles,(path,target)
    body='<p>'+prose(item['summary'])+'</p>'
    for heading,content in item['blocks']:
        body+='<h2>'+html.escape(heading)+'</h2><p>'+prose(content)+'</p>'
    body+='<h2>Implementation contract</h2><pre><code class="language-'+item['language']+'">'+html.escape(item['code'],quote=False)+'</code></pre>'
    body+='<h2>Cost and verification</h2><p>'+prose(item['cost'])+'</p>'
    body+='<h3>Common Mistakes</h3><ul>'+''.join('<li>'+prose(mistake)+'</li>' for mistake in item['mistakes'])+'</ul>'
    body+='<h2>Read next</h2><p>'+', '.join('<a href="/'+target+'">'+html.escape(titles[target])+'</a>' for target in item['related'])+'.</p>'
    row=copy.deepcopy(by_path['spring/component-scan-vs-bean'])
    row.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://aitrove.in/'+path)),path=path,title=item['title'],summary=item['summary'],body=body,subject='spring-security',tags=['spring','spring-security',item['slug']],sort_order=6300+number,published_at=stamp,created_at=stamp,updated_at=stamp)
    row['data']={'subject_root':'spring/spring-boot','section_path':'spring/security','kind':'tutorial','content_format':'html','seo_ready':True,'reading_minutes':max(4,round(len(re.sub(r'<[^>]+>',' ',body).split())/150)),'author_path':'authors/aitrove-editorial','framework_version':'Spring Security 7 / Spring Boot 4 where relevant','java_version':'21 or later','verification_suite':'Spring Security API contract review; snippets require an application-specific model','related':[{'path':target,'title':titles[target]} for target in item['related']]}
    rows.append(row);by_path[path]=row

hub=by_path['spring/security']
new_paths=['spring/'+item['slug'] for item in lessons]
hub['data']['modules'].append({'title':'Security chain and token boundaries','summary':'Route coverage, stateless APIs, token claims, clock tolerance, SPA CSRF, introspection, CSP and ownership checks.','lessons':new_paths})
hub['body']+='<h2>Security chain and token boundaries</h2><ul>'+''.join('<li><a href="/'+path+'">'+html.escape(titles[path])+'</a></li>' for path in new_paths)+'</ul>'
hub['updated_at']=stamp
parent=by_path['spring/spring-boot']
parent['body']+='<h2>Security chain and token boundaries</h2><p><a href="/spring/security">Spring Security</a> now includes <a href="/spring/security-multiple-filter-chains">multiple filter chains</a>, <a href="/spring/jwt-authority-claim-mapping">JWT authority mapping</a> and <a href="/spring/spa-csrf-token-refresh">SPA CSRF token refresh</a>.</p>'
parent['updated_at']=stamp
for item in lessons:
    source,target=item['backlink'],'spring/'+item['slug']
    entry=by_path[source]
    entry['body']+='<h2>Related security contract</h2><p><a href="/'+target+'">'+html.escape(titles[target])+'</a>.</p>'
